<pre><code class="language-sql">CREATE TABLE lab (id bigint PRIMARY KEY, code varchar(20) NOT NULL UNIQUE);
CREATE TABLE equipment (                       -- Lab 0..1 &lt;&gt;-- * Equipment (aggregation)
  id        bigint PRIMARY KEY,
  asset_tag varchar(30) NOT NULL UNIQUE,
  lab_id    bigint REFERENCES lab (id) ON DELETE SET NULL
);
CREATE TABLE reservation (id bigint PRIMARY KEY, code varchar(20) NOT NULL UNIQUE,
  lab_id bigint NOT NULL REFERENCES lab (id) ON DELETE RESTRICT);
CREATE TABLE reservation_item (               -- Reservation 1 &lt;*&gt;-- * ReservationItem (composition)
  id             bigint PRIMARY KEY,
  reservation_id bigint NOT NULL REFERENCES reservation (id) ON DELETE CASCADE,
  equipment_id   bigint NOT NULL REFERENCES equipment (id) ON DELETE RESTRICT,
  quantity       int    NOT NULL CHECK (quantity &gt; 0)
);
INSERT INTO lab VALUES (1, 'B201'), (2, 'B305');
INSERT INTO equipment VALUES (10, 'OSC-01', 1), (11, 'OSC-02', 1), (12, 'PI-07', 2);
INSERT INTO reservation VALUES (100, 'R-1001', 2);
INSERT INTO reservation_item VALUES (1, 100, 10, 1), (2, 100, 12, 2);

DELETE FROM lab WHERE id = 1;                 -- aggregation: parts survive
SELECT asset_tag, lab_id FROM equipment ORDER BY id;
DELETE FROM lab WHERE id = 2;                 -- still has a reservation -&gt; RESTRICT
DELETE FROM equipment WHERE id = 10;          -- still booked -&gt; RESTRICT
DELETE FROM reservation WHERE id = 100;       -- composition: parts die
SELECT count(*) AS items_left FROM reservation_item;
SELECT count(*) AS equipment_left FROM equipment;</code></pre>
